 "content": "def transform(grid):
    """Encode the counts of horizontal 3- and 2-colored bars in a 2x3 grid."""
    counts = {3: 0, 2: 0}
    for row in grid:
        previous = None
        for value in row:
            if value in counts and value != previous:
                counts[value] += 1
            previous = value
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
